import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { CacheBreak, CacheRequest, Tab, TurnStat } from '../types'
import { hash, short } from './format'
import {
  EMPTY_SIGNALS,
  EMPTY_TOTALS,
  KEEP_BREAKS,
  KEEP_REQUESTS,
  KEEP_TURNS,
  PANE,
  checkAlerts,
  refreshGit,
  refreshStatus,
  resetAll,
  safe,
} from './state'
import type { Options } from './state'
import { drawPane } from './view'

const breaks = atom({ plugin: 'session-info', key: 'breaks' } as const, [])
const requests = atom({ plugin: 'session-info', key: 'requests' } as const, [])
const signals = atom({ plugin: 'session-info', key: 'signals' } as const, EMPTY_SIGNALS)
const tab = atom({ plugin: 'session-info', key: 'tab' } as const, 'overview' as Tab)
const tick = atom({ plugin: 'session-info', key: 'tick' } as const, 0)
const tools = atom({ plugin: 'session-info', key: 'tools' } as const, [])
const totals = atom({ plugin: 'session-info', key: 'totals' } as const, EMPTY_TOTALS)
const turn = atom({ plugin: 'session-info', key: 'turn' } as const, null)
const turns = atom({ plugin: 'session-info', key: 'turns' } as const, [])

const TICK_MS = 15_000
const GIT_EVERY = 4
const TABS: readonly Tab[] = ['overview', 'context', 'cache', 'turns']

/**
 * Why a request read far less from the cache than the one before it had
 * cached. A heuristic over what the mod saw between the two requests.
 */
function causeOf(prev: CacheRequest, cur: CacheRequest, startedAt: number, compactedAt: number, promptChangedAt: number, ttlMs: number) {
  if (compactedAt > prev.at) return 'Compaction: the conversation was summarized'
  if (cur.model !== prev.model) return `Model switch: ${prev.model} → ${cur.model}`
  const idle = startedAt - prev.at
  if (idle >= ttlMs) return `TTL expired after ${short(idle)} idle`
  if (promptChangedAt > prev.at) return 'System prompt or tool list changed'
  if (cur.cacheRead === 0) return 'Cache evicted early: nothing was read while the TTL was still warm'
  return 'Prefix changed: earlier context was edited or reordered'
}

export const register: Register = (on, options) => {
  const opts: Options = {
    ttlMs: options.cacheTtl === '5m' ? 5 * 60_000 : 60 * 60_000,
    ttlLabel: options.cacheTtl === '5m' ? '5m' : '1h',
    alertMode: options.alerts === 'off' ? 'off' : options.alerts === 'toast+native' ? 'toast+native' : 'toast',
  }

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'session-info',
      description: 'Session dashboard: context, prompt cache, turns, cost and limits',
      argumentHint: '[overview|context|cache|turns]',
    })
    let ticks = 0
    $.clock.every(TICK_MS, () => {
      ticks += 1
      void update($, tick, n => (n ?? 0) + 1)
      void refreshStatus($, opts)
      void checkAlerts($, opts)
      if (ticks % GIT_EVERY === 0) void refreshGit($)
    })
    void refreshStatus($, opts)
    void refreshGit($)

    return next(e)
  })

  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear') {
      await resetAll($)
      $.ui.status(undefined)
    }

    return next(e)
  })

  on('command.run', { command: 'session-info' }, async ($, e) => {
    const wanted = e.args.trim().toLowerCase()
    if ((TABS as readonly string[]).includes(wanted)) await update($, tab, () => wanted as Tab)
    const { isPlaced } = await $.ui.open({ id: PANE, title: 'Session' })

    return { text: isPlaced ? 'Session dashboard opened.' : 'The session dashboard needs a surface that shows panes.' }
  })

  // The prompt each request is built from: a new combination of system prompt
  // and tools, after the first, may explain a cache break that follows.
  on('prompt.compose', async ($, e, next) => {
    const result = await next(e)
    const key = hash(`${e.model}|${e.tools.join(',')}|${result.sections.map(s => s.text).join('\n')}`)
    const was = await read($, signals)
    const seen = was.promptKey.split(',').filter(k => k.length > 0)
    if (!seen.includes(key)) {
      const now = await $.clock.now()
      await update($, signals, s => ({
        ...s,
        promptKey: [...seen, key].slice(-6).join(','),
        promptChangedAt: seen.length > 0 ? now : s.promptChangedAt,
      }))
    }

    return result
  })

  on('session.compact', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId === undefined && result.skip === undefined) {
      const now = await $.clock.now()
      await update($, signals, s => ({ ...s, compactedAt: now }))
    }

    return result
  }).catch(($, e, next) => next(e))

  on('turn.start', async ($, e, next) => {
    if (e.agentId === undefined) {
      const [now, usage] = await Promise.all([$.clock.now(), safe(() => $.session.usage())])
      await update($, turn, () => ({
        turnId: e.turnId,
        startedAt: now,
        costAtStart: usage?.cost?.usd ?? 0,
        requests: 0,
        tools: 0,
        errors: 0,
      }))
    }

    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    if (e.agentId !== undefined) return next(e)
    const startedAt = await $.clock.now()
    const result = await next(e)
    const ms = (await $.clock.now()) - startedAt
    const isError = 'deny' in result ? result.deny !== undefined : result.isError === true
    const name = String(e.tool)

    await update($, tools, list => {
      const all = list ?? []
      const found = all.find(t => t.tool === name)
      const row = found ?? { tool: name, calls: 0, errors: 0, totalMs: 0 }
      const bumped = { ...row, calls: row.calls + 1, errors: row.errors + (isError ? 1 : 0), totalMs: row.totalMs + ms }
      return found ? all.map(t => (t.tool === name ? bumped : t)) : [...all, bumped]
    })
    await update($, turn, t => (t ? { ...t, tools: t.tools + 1, errors: t.errors + (isError ? 1 : 0) } : t))

    return result
  }).catch(($, e, next) => next(e))

  // Every API request: what the prompt cache served and wrote, and whether
  // it had to re-cache a prefix the request before it had cached.
  on('turn.step', async function* ($, e, next) {
    const startedAt = await $.clock.now()
    const result = yield* next(e)
    const usage = result.usage
    if (usage === null) return result

    if (e.agentId !== undefined) {
      await update($, totals, t => ({ ...(t ?? EMPTY_TOTALS), subagentRequests: (t ?? EMPTY_TOTALS).subagentRequests + 1 }))
      return result
    }

    const [list, sig, now] = await Promise.all([read($, requests), read($, signals), $.clock.now()])
    const request: CacheRequest = {
      at: now,
      model: usage.model,
      input: usage.input_tokens,
      cacheRead: usage.cache_read_input_tokens,
      cacheWrite: usage.cache_creation_input_tokens,
      output: usage.output_tokens,
    }

    const prev = list.at(-1)
    if (prev !== undefined) {
      const expected = prev.cacheRead + prev.cacheWrite
      if (expected > 2048 && request.cacheRead < expected * 0.6 && request.cacheWrite > 2048) {
        request.isBreak = true
        const found: CacheBreak = {
          at: now,
          rewritten: request.cacheWrite,
          read: request.cacheRead,
          expected,
          cause: causeOf(prev, request, startedAt, sig.compactedAt, sig.promptChangedAt, opts.ttlMs),
        }
        await update($, breaks, b => [...(b ?? []), found].slice(-KEEP_BREAKS))
        if (opts.alertMode !== 'off' && !found.cause.startsWith('Compaction') && !found.cause.startsWith('TTL')) {
          $.ui.toast(`Cache break: ${found.cause}`)
        }
      }
    }

    await update($, requests, l => [...(l ?? []), request].slice(-KEEP_REQUESTS))
    await update($, totals, t => {
      const was = t ?? EMPTY_TOTALS
      return {
        ...was,
        requests: was.requests + 1,
        input: was.input + request.input,
        cacheRead: was.cacheRead + request.cacheRead,
        cacheWrite: was.cacheWrite + request.cacheWrite,
        output: was.output + request.output,
      }
    })
    await update($, turn, t => (t ? { ...t, requests: t.requests + 1 } : t))
    await refreshStatus($, opts)
    await checkAlerts($, opts)

    return result
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined) {
      const [running, usage, now] = await Promise.all([read($, turn), safe(() => $.session.usage()), $.clock.now()])
      const stat: TurnStat = {
        at: now,
        durationMs: e.durationMs,
        requests: running?.requests ?? 0,
        tools: running?.tools ?? 0,
        errors: running?.errors ?? 0,
        costUsd: Math.max(0, (usage?.cost?.usd ?? 0) - (running?.costAtStart ?? 0)),
        outputTokens: e.usage?.output_tokens ?? 0,
        reason: e.reason,
      }
      await update($, turns, list => [...(list ?? []), stat].slice(-KEEP_TURNS))
      await update($, turn, () => null)
      void refreshGit($)
    }

    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: 'session-info' }, ($, e) => drawPane($, e, opts))
}

