import type { CacheRequest } from '../types'

// Palette: the dataviz reference palette's dark-surface steps, which hold 3:1
// on both light and dark surfaces, so one SVG reads in either theme. Labels
// always sit beside colored marks, never inside them.

export const SERIES = ['#3987e5', '#d95926', '#199e70', '#c98500', '#d55181', '#008300', '#9085e9', '#e66767']
export const STATUS = { good: '#0ca30c', warning: '#fab219', serious: '#ec835a', critical: '#d03b3b' }
export const ACCENT = '#3987e5'
export const TRACK = 'rgba(128,128,128,0.22)'
export const RULE = 'rgba(128,128,128,0.55)'

// Numbers

export const tokens = (n: number): string =>
  n >= 1_000_000
    ? `${(n / 1_000_000).toFixed(2)}M`
    : n >= 10_000
      ? `${Math.round(n / 1000)}k`
      : n >= 1000
        ? `${(n / 1000).toFixed(1)}k`
        : String(Math.round(n))

/** Context-style counts: `314`, `18.6k`, `33k`, `281.4k`, `1M`, `1.25M`. */
export const tok1 = (n: number): string =>
  n < 1000
    ? String(Math.round(n))
    : n < 1_000_000
      ? `${(n / 1000).toFixed(1).replace(/\.0$/, '')}k`
      : `${(n / 1_000_000).toFixed(2).replace(/\.?0+$/, '')}M`

/** One decimal: `22.6%`, `0.0%`. */
export const pct1 = (part: number, whole: number): string => `${whole > 0 ? ((part / whole) * 100).toFixed(1) : '0.0'}%`

export const NEUTRAL = '#a3a29c'

export const duration = (ms: number): string => {
  const s = Math.max(0, Math.round(ms / 1000))
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  if (m < 60) return `${m}m ${String(s % 60).padStart(2, '0')}s`
  const h = Math.floor(m / 60)
  if (h < 48) return `${h}h ${String(m % 60).padStart(2, '0')}m`
  return `${Math.floor(h / 24)}d ${h % 24}h`
}

export const short = (ms: number): string => {
  const s = Math.max(0, Math.round(ms / 1000))
  if (s < 60) return `${s}s`
  const m = Math.round(s / 60)
  return m < 60 ? `${m}m` : `${Math.floor(m / 60)}h${m % 60 > 0 ? ` ${m % 60}m` : ''}`
}

export const clock = (ms: number): string => {
  const d = new Date(ms)
  const p = (n: number) => String(n).padStart(2, '0')
  return `${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`
}

export const usd = (n: number): string => (n >= 100 ? `$${n.toFixed(0)}` : n >= 1 ? `$${n.toFixed(2)}` : `$${n.toFixed(3)}`)

export const percent = (part: number, whole: number): number =>
  whole > 0 ? Math.round((part / whole) * 100) : 0

export const clamp = (n: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, n))

// The prompt a request was answered over: uncached, read and written together.
export const promptOf = (r: { input: number; cacheRead: number; cacheWrite: number }) =>
  r.input + r.cacheRead + r.cacheWrite

export const hitOf = (r: CacheRequest) => percent(r.cacheRead, promptOf(r))

export const limitName = (kind: string): string =>
  kind === 'five_hour' ? '5-hour' : kind === 'seven_day' ? '7-day' : kind.replace(/_/g, ' ')

/** Higher is worse: good under `warn`, warning under `bad`, critical above. */
export const level = (pct: number, warn: number, bad: number) =>
  pct >= bad ? STATUS.critical : pct >= warn ? STATUS.warning : STATUS.good

export const hash = (text: string): string => {
  let h = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 0x01000193)
  }
  return (h >>> 0).toString(36)
}

// Cache status

export type CacheState =
  | { kind: 'none' }
  | { kind: 'warm'; remainingMs: number; last: CacheRequest }
  | { kind: 'expired'; agoMs: number; last: CacheRequest }

export const cacheState = (list: readonly CacheRequest[], now: number, ttlMs: number): CacheState => {
  const last = list.at(-1)
  if (last === undefined) return { kind: 'none' }
  const age = now - last.at
  return age < ttlMs ? { kind: 'warm', remainingMs: ttlMs - age, last } : { kind: 'expired', agoMs: age, last }
}

// Text charts, for surfaces without SVG

const BLOCKS = '▁▂▃▄▅▆▇█'

export const blockOf = (fraction: number): string =>
  BLOCKS[clamp(Math.round(fraction * (BLOCKS.length - 1)), 0, BLOCKS.length - 1)] ?? '▁'

export const textBar = (fraction: number, width: number): [string, string] => {
  const filled = clamp(Math.round(fraction * width), 0, width)
  return ['█'.repeat(filled), '░'.repeat(width - filled)]
}

// SVG charts. Marks only: every label is a Text beside the chart, so text
// wears the surface's own ink in light and dark alike.

const svg = (w: number, h: number, body: string) =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">${body}</svg>`

const esc = (s: string) => s.replace(/[<>&"]/g, c => `&#${c.charCodeAt(0)};`)

/** A ring gauge: `fraction` of the circle in `color` over a neutral track. */
export const ringSvg = (fraction: number, color: string, size = 64, stroke = 7): string => {
  const r = (size - stroke) / 2
  const c = 2 * Math.PI * r
  const f = clamp(fraction, 0, 1)
  const arc =
    f > 0
      ? `<circle cx="${size / 2}" cy="${size / 2}" r="${r}" fill="none" stroke="${color}" stroke-width="${stroke}" stroke-linecap="round" stroke-dasharray="${(c * f).toFixed(2)} ${c.toFixed(2)}" transform="rotate(-90 ${size / 2} ${size / 2})"/>`
      : ''
  return svg(
    size,
    size,
    `<circle cx="${size / 2}" cy="${size / 2}" r="${r}" fill="none" stroke="${TRACK}" stroke-width="${stroke}"/>${arc}`,
  )
}

export type Segment = { fraction: number; color: string; label: string }

/**
 * One horizontal stacked bar: segments left to right with 2px surface gaps,
 * the rest as track, rounded ends, and an optional marker (a threshold).
 */
export const stackedSvg = (segments: readonly Segment[], width = 640, height = 14, marker?: number): string => {
  const pad = marker !== undefined ? 3 : 0
  const gap = 2
  let x = 0
  const parts: string[] = [`<rect x="0" y="${pad}" width="${width}" height="${height}" rx="${height / 2}" fill="${TRACK}"/>`]
  const shown = segments.filter(s => s.fraction * width >= 1)
  shown.forEach((s, i) => {
    const w = Math.max(1, s.fraction * width - (i < shown.length - 1 ? gap : 0))
    parts.push(`<rect x="${x.toFixed(1)}" y="${pad}" width="${w.toFixed(1)}" height="${height}" fill="${s.color}"><title>${esc(s.label)}</title></rect>`)
    x += s.fraction * width
  })
  // Round both ends of the whole bar by clipping to a pill.
  const clip = `<clipPath id="pill"><rect x="0" y="${pad}" width="${width}" height="${height}" rx="${height / 2}"/></clipPath>`
  const mark =
    marker !== undefined
      ? `<line x1="${(marker * width).toFixed(1)}" x2="${(marker * width).toFixed(1)}" y1="0" y2="${height + 2 * pad}" stroke="${RULE}" stroke-width="2" stroke-dasharray="3 2"/>`
      : ''
  return svg(width, height + 2 * pad, `<defs>${clip}</defs><g clip-path="url(#pill)">${parts.join('')}</g>${mark}`)
}

export type Column = { value: number; color: string; label: string }

/**
 * Vertical columns, one per datum, rounded at the data end and anchored to a
 * baseline; `max` fixes the scale (100 for a percentage), else the data's own.
 */
export const columnsSvg = (cols: readonly Column[], width = 640, height = 64, max?: number, guide?: number): string => {
  const n = Math.max(cols.length, 1)
  const slot = width / Math.max(n, 24)
  const bar = Math.max(2, slot - 2)
  const top = max ?? Math.max(1, ...cols.map(c => c.value))
  const body: string[] = [`<line x1="0" x2="${width}" y1="${height - 0.5}" y2="${height - 0.5}" stroke="${TRACK}" stroke-width="1"/>`]
  if (guide !== undefined) {
    const y = height - (guide / top) * (height - 2)
    body.push(`<line x1="0" x2="${width}" y1="${y.toFixed(1)}" y2="${y.toFixed(1)}" stroke="${RULE}" stroke-width="1" stroke-dasharray="4 3"/>`)
  }
  const offset = width - n * slot
  cols.forEach((c, i) => {
    const h = Math.max(2, (clamp(c.value, 0, top) / top) * (height - 2))
    const x = offset + i * slot
    const r = Math.min(2, bar / 2)
    body.push(
      `<path d="M${x.toFixed(1)},${height} v${-(h - r).toFixed(1)} q0,${-r} ${r},${-r} h${(bar - 2 * r).toFixed(1)} q${r},0 ${r},${r} v${(h - r).toFixed(1)} z" fill="${c.color}"><title>${esc(c.label)}</title></path>`,
    )
  })
  return svg(width, height, body.join(''))
}

/** A thin single-value bar for table rows. */
export const meterSvg = (fraction: number, color: string, width = 160, height = 8): string =>
  svg(
    width,
    height,
    `<rect x="0" y="0" width="${width}" height="${height}" rx="${height / 2}" fill="${TRACK}"/>` +
      (fraction > 0
        ? `<rect x="0" y="0" width="${Math.max(height, clamp(fraction, 0, 1) * width).toFixed(1)}" height="${height}" rx="${height / 2}" fill="${color}"/>`
        : ''),
  )

/** A small rounded square for a legend row. */
export const swatchSvg = (color: string, size = 10): string =>
  svg(size, size, `<rect x="0" y="0" width="${size}" height="${size}" rx="${size / 4}" fill="${color}"/>`)

