import { atom, read, update } from 'claude-code'
import type { EngineInterface } from 'claude-code'

import type { Alerts, CacheTotals, GitInfo, Signals, Tab } from '../types'
import { cacheState, hitOf, promptOf, short, tokens, usd } from './format'

export const PLUGIN = 'session-info'
export const PANE = 'session-info'
export const KEEP_REQUESTS = 50
export const KEEP_TURNS = 30
export const KEEP_BREAKS = 20

export const EMPTY_TOTALS: CacheTotals = {
  requests: 0,
  input: 0,
  cacheRead: 0,
  cacheWrite: 0,
  output: 0,
  subagentRequests: 0,
}
export const EMPTY_SIGNALS: Signals = { compactedAt: 0, promptKey: '', promptChangedAt: 0 }
export const EMPTY_ALERTS: Alerts = { expiryFor: 0, contextLevel: 0 }

export const requests = atom({ plugin: 'session-info', key: 'requests' } as const, [])
export const totals = atom({ plugin: 'session-info', key: 'totals' } as const, EMPTY_TOTALS)
export const tick = atom({ plugin: 'session-info', key: 'tick' } as const, 0)
export const breaks = atom({ plugin: 'session-info', key: 'breaks' } as const, [])
export const turns = atom({ plugin: 'session-info', key: 'turns' } as const, [])
export const turn = atom({ plugin: 'session-info', key: 'turn' } as const, null)
export const tools = atom({ plugin: 'session-info', key: 'tools' } as const, [])
export const signals = atom({ plugin: 'session-info', key: 'signals' } as const, EMPTY_SIGNALS)
export const alerts = atom({ plugin: 'session-info', key: 'alerts' } as const, EMPTY_ALERTS)
export const git = atom({ plugin: 'session-info', key: 'git' } as const, null)
export const tab = atom({ plugin: 'session-info', key: 'tab' } as const, 'overview' as Tab)

export type Options = {
  ttlMs: number
  ttlLabel: string
  alertMode: 'toast' | 'toast+native' | 'off'
}

/** Context levels that raise an alert as the window fills past each. */
const CONTEXT_LEVELS = [70, 85, 95]

/** A $ call that may be unavailable on a surface or in a test reads as undefined. */
export async function safe<T>(call: () => Promise<T>): Promise<T | undefined> {
  try {
    return await call()
  } catch {
    return undefined
  }
}

/** The pinned line under the prompt: cache warmth, hit rate, context, cost. */
export async function refreshStatus($: EngineInterface, opts: Options) {
  const [list, now, usage] = await Promise.all([read($, requests), $.clock.now(), safe(() => $.session.usage())])
  const state = cacheState(list, now, opts.ttlMs)
  const parts: string[] = []

  if (state.kind === 'warm') {
    parts.push(`◆ cache warm ${short(state.remainingMs)} · hit ${hitOf(state.last)}%`)
  } else if (state.kind === 'expired') {
    parts.push(`◇ cache cold · idle ${short(state.agoMs)}`)
  }
  if (usage?.context.percent !== undefined) parts.push(`ctx ${usage.context.percent}%`)
  if (usage?.cost !== undefined) parts.push(usd(usage.cost.usd))

  $.ui.status(parts.length > 0 ? parts.join(' · ') : undefined)
}

function alert($: EngineInterface, opts: Options, text: string) {
  $.ui.toast(text)
  if (opts.alertMode === 'toast+native') void safe(() => $.ui.notify(text, { title: 'Session info' }))
}

/** Warns once before the cache goes cold, and once per context level crossed. */
export async function checkAlerts($: EngineInterface, opts: Options) {
  if (opts.alertMode === 'off') return
  const [list, now, fired, usage] = await Promise.all([
    read($, requests),
    $.clock.now(),
    read($, alerts),
    safe(() => $.session.usage()),
  ])
  const state = cacheState(list, now, opts.ttlMs)
  const warnMs = opts.ttlMs <= 5 * 60_000 ? 60_000 : 5 * 60_000
  let next = fired

  if (state.kind === 'warm' && state.remainingMs <= warnMs && fired.expiryFor !== state.last.at) {
    const resend = promptOf(state.last) + state.last.output
    alert($, opts, `Prompt cache expires in ${short(state.remainingMs)}; the next request re-caches ~${tokens(resend)} tokens`)
    next = { ...next, expiryFor: state.last.at }
  }

  const pct = usage?.context.percent
  if (pct !== undefined) {
    const reached = CONTEXT_LEVELS.filter(l => pct >= l).at(-1) ?? 0
    if (reached > fired.contextLevel) {
      alert($, opts, `Context window ${pct}% full${reached >= 85 ? ', consider /compact' : ''}`)
    }
    if (reached !== fired.contextLevel) next = { ...next, contextLevel: reached }
  }

  if (next !== fired) await update($, alerts, () => next)
}

/** Reads the branch, its distance from upstream and the count of changed files. */
export async function refreshGit($: EngineInterface) {
  const run = await safe(() => $.process.run(['git', 'status', '--porcelain=v2', '--branch'], { timeoutMs: 5000 }))
  let info: GitInfo | null = null
  if (run !== undefined && run.exitCode === 0) {
    info = { branch: 'detached', dirty: 0, ahead: 0, behind: 0 }
    for (const line of run.stdout.split('\n')) {
      if (line.startsWith('# branch.head ')) info.branch = line.slice(14)
      else if (line.startsWith('# branch.ab ')) {
        const [a, b] = line.slice(12).split(' ')
        info.ahead = Math.abs(Number(a) || 0)
        info.behind = Math.abs(Number(b) || 0)
      } else if (line.length > 0 && !line.startsWith('#')) info.dirty += 1
    }
  }
  const was = await read($, git)
  if (JSON.stringify(was) !== JSON.stringify(info)) await update($, git, () => info)
}

export async function resetAll($: EngineInterface) {
  await Promise.all([
    update($, requests, () => []),
    update($, totals, () => EMPTY_TOTALS),
    update($, breaks, () => []),
    update($, turns, () => []),
    update($, turn, () => null),
    update($, tools, () => []),
    update($, signals, () => EMPTY_SIGNALS),
    update($, alerts, () => EMPTY_ALERTS),
  ])
}

