import { atom, read, update } from 'claude-code'
import type { EngineInterface, Frozen, RenderElement, RenderInput, SessionContextBreakdown } from 'claude-code'

import type { Tab } from '../types'
import {
  ACCENT,
  NEUTRAL,
  RULE,
  SERIES,
  TRACK,
  STATUS,
  blockOf,
  cacheState,
  clamp,
  clock,
  columnsSvg,
  duration,
  hitOf,
  level,
  limitName,
  meterSvg,
  pct1,
  percent,
  promptOf,
  ringSvg,
  short,
  stackedSvg,
  swatchSvg,
  textBar,
  tok1,
  tokens,
  usd,
} from './format'
import type { Column, Segment } from './format'
import { EMPTY_TOTALS, safe } from './state'
import type { Options } from './state'

const breaks = atom({ plugin: 'session-info', key: 'breaks' } as const, [])
const expanded = atom({ plugin: 'session-info', key: 'expanded' } as const, [])
const git = atom({ plugin: 'session-info', key: 'git' } as const, null)
const requests = atom({ plugin: 'session-info', key: 'requests' } as const, [])
const tab = atom({ plugin: 'session-info', key: 'tab' } as const, 'overview' as Tab)
const tick = atom({ plugin: 'session-info', key: 'tick' } as const, 0)
const tools = atom({ plugin: 'session-info', key: 'tools' } as const, [])
const totals = atom({ plugin: 'session-info', key: 'totals' } as const, EMPTY_TOTALS)
const turn = atom({ plugin: 'session-info', key: 'turn' } as const, null)
const turns = atom({ plugin: 'session-info', key: 'turns' } as const, [])

const TAB_LABELS: readonly [Tab, string][] = [
  ['overview', 'Overview'],
  ['context', 'Context'],
  ['cache', 'Cache'],
  ['turns', 'Turns'],
]

/** `claude-opus-5-5` → `Opus 5.5`; anything else as given. */
const modelName = (id: string): string => {
  const m = /^claude-([a-z]+)-(\d+)-(\d+)/.exec(id)
  if (m === null) return id
  const [, family = '', major, minor] = m
  return `${family.charAt(0).toUpperCase()}${family.slice(1)} ${major}.${minor}`
}

const tail = (path: string, parts = 2) => path.split('/').filter(Boolean).slice(-parts).join('/')

export async function drawPane($: EngineInterface, e: Frozen<RenderInput<'Pane'>>, opts: Options): Promise<RenderElement> {
  const els = $.ui.resolve(e)
  const { Box, Text, Button } = els
  const Svg = 'Svg' in els ? els.Svg : undefined
  const rich = Svg !== undefined

  await read($, tick)
  const [current, open, list, sum, cut, done, running, toolStats, repo, now] = await Promise.all([
    read($, tab),
    read($, expanded),
    read($, requests),
    read($, totals),
    read($, breaks),
    read($, turns),
    read($, turn),
    read($, tools),
    read($, git),
    $.clock.now(),
  ])
  const needsBreakdown = current === 'overview' || current === 'context'
  const [usage, model, id, prompts, version, cwd] = await Promise.all([
    safe(() => $.session.usage(needsBreakdown ? { breakdown: 'summary', columns: e.props.bodyColumns } : undefined)),
    safe(() => $.session.model()),
    safe(() => $.session.id()),
    safe(() => $.session.turns()),
    safe(() => $.session.version()),
    safe(() => $.session.cwd()),
  ])

  const cols = Math.max(30, e.props.bodyColumns)
  const wide = cols >= 84
  const barChars = clamp(cols - 8, 16, 60)
  const cache = cacheState(list, now, opts.ttlMs)
  const warnMs = opts.ttlMs <= 5 * 60_000 ? 60_000 : 5 * 60_000
  const ctx = usage?.context
  const ctxPct = ctx?.percent ?? 0
  const breakdown = usage?.context.breakdown
  const sessionHit = percent(sum.cacheRead, promptOf(sum))

  // Typography: the desktop's type scale where it has one, weight and ink in a terminal.
  const title = rich ? ({ size: 'title', weight: 'semibold', tabular: true } as const) : ({ bold: true } as const)
  const heading = rich ? ({ size: 'heading', weight: 'semibold' } as const) : ({ bold: true } as const)
  const caption = rich ? ({ size: 'caption', dimColor: true } as const) : ({ dimColor: true } as const)
  const num = rich ? ({ tabular: true } as const) : ({} as const)

  // Pieces

  const label = (text: string) => <Text {...caption}>{rich ? text : text.toUpperCase()}</Text>

  const swatch = (color: string, key?: string) => (
    <Text key={key} color={color}>
      ■
    </Text>
  )

  const card = (key: string, name: string, children: RenderElement[], width?: string) => (
    <Box
      key={key}
      flexDirection="column"
      borderStyle="round"
      borderColor="subtle"
      paddingX={1}
      flexGrow={1}
      width={width ?? (wide ? '49%' : '100%')}
      marginBottom={1}
    >
      {label(name)}
      {children}
    </Box>
  )

  const stat = (key: string, name: string, value: string, color?: string) => (
    <Box key={key} flexDirection="column" marginRight={3}>
      {label(name)}
      <Text {...heading} {...num} color={color}>
        {value}
      </Text>
    </Box>
  )

  const line = (key: string, name: string, value: string, color?: string) => (
    <Box key={key} justifyContent="space-between">
      <Text dimColor>{name}</Text>
      <Text {...num} color={color} wrap="truncate-start">
        {value}
      </Text>
    </Box>
  )

  /** A gauge: a ring on desktop, a bar of blocks in a terminal. */
  const gauge = (key: string, fraction: number, color: string, alt: string) =>
    Svg !== undefined ? (
      <Svg key={key} source={ringSvg(fraction, color)} alt={alt} width={64} height={64} />
    ) : (
      <Text key={key}>
        <Text color={color}>{textBar(fraction, 12)[0]}</Text>
        <Text dimColor>{textBar(fraction, 12)[1]}</Text>
      </Text>
    )

  /** Columns: an SVG chart on desktop, a sparkline of blocks in a terminal. */
  const chart = (key: string, data: readonly Column[], alt: string, height: number, max?: number, guide?: number) =>
    Svg !== undefined ? (
      <Svg key={key} source={columnsSvg(data, 640, height, max, guide)} alt={alt} isInteractive />
    ) : (
      <Text key={key}>
        {data.slice(-barChars).map((c, i) => (
          <Text key={String(i)} color={c.color}>
            {blockOf(c.value / (max ?? Math.max(1, ...data.map(d => d.value))))}
          </Text>
        ))}
      </Text>
    )

  /** One stacked bar: an SVG with a dashed threshold on desktop, colored blocks in a terminal. */
  const stacked = (key: string, segments: readonly Segment[], alt: string, marker?: number) => {
    if (Svg !== undefined) {
      return <Svg key={key} source={stackedSvg(segments, 640, 14, marker)} alt={alt} isInteractive />
    }
    let used = 0
    const parts = segments.map((s, i) => {
      const n = i === segments.length - 1 ? Math.max(0, barChars - used) : Math.round(s.fraction * barChars)
      used += n
      return s.color === 'transparent' ? (
        <Text key={String(i)} dimColor>
          {'░'.repeat(n)}
        </Text>
      ) : (
        <Text key={String(i)} color={s.color}>
          {'█'.repeat(n)}
        </Text>
      )
    })
    return (
      <Box key={key} flexDirection="column">
        <Text>{parts}</Text>
        {marker !== undefined && <Text dimColor>{`${' '.repeat(Math.max(0, Math.round(marker * barChars) - 1))}▲ auto-compact`}</Text>}
      </Box>
    )
  }

  const legend = (key: string, items: readonly [string, string][]) => (
    <Box key={key} flexWrap="wrap" columnGap={2}>
      {items.map(([color, text]) => (
        <Text key={text}>
          <Text color={color}>■</Text> <Text dimColor>{text}</Text>
        </Text>
      ))}
    </Box>
  )

  const hitColumns: Column[] = list.map(r => ({
    value: hitOf(r),
    color: r.isBreak === true ? STATUS.critical : ACCENT,
    label: `${clock(r.at)} · ${hitOf(r)}% hit · read ${tokens(r.cacheRead)} · wrote ${tokens(r.cacheWrite)}${r.isBreak === true ? ' · cache break' : ''}`,
  }))

  // Header: who, where the cache stands, what it cost; then the tabs.

  const pill =
    cache.kind === 'warm'
      ? { text: `● Cache warm · ${short(cache.remainingMs)}`, color: cache.remainingMs <= warnMs ? STATUS.warning : STATUS.good }
      : cache.kind === 'expired'
        ? { text: `○ Cache cold · idle ${short(cache.agoMs)}`, color: STATUS.serious }
        : { text: '○ No requests yet', color: RULE }

  const header = (
    <Box key="header" flexDirection="column" marginBottom={1}>
      <Box justifyContent="space-between" flexWrap="wrap">
        <Text {...heading}>{modelName(model ?? 'Claude')}</Text>
        <Box columnGap={2}>
          <Text color={pill.color}>{pill.text}</Text>
          {usage?.cost !== undefined && (
            <Text {...num} bold>
              {usd(usage.cost.usd)}
            </Text>
          )}
        </Box>
      </Box>
      <Box columnGap={1} marginTop={1}>
        {TAB_LABELS.map(([t, name], i) => (
          <Button
            key={`tab-${t}`}
            label={name}
            hotkey={String(i + 1)}
            variant={t === current ? 'primary' : 'secondary'}
            onPress={() => update($, tab, () => t)}
          />
        ))}
      </Box>
    </Box>
  )

  // Context

  type Row = { name: string; tokens: number; color: string; dim?: boolean; empty?: boolean }

  /** The breakdown as rows, largest first: four hues, then neutral; buffer and free after. */
  const contextRows = (b: SessionContextBreakdown) => {
    const used: Row[] = b.categories
      .filter(c => c.kind === 'used' && c.tokens > 0)
      .sort((x, y) => y.tokens - x.tokens)
      .map((c, i) => ({ name: c.name, tokens: c.tokens, color: i < 4 ? (SERIES[i] ?? NEUTRAL) : NEUTRAL }))
    const buffer = b.categories.find(c => c.kind === 'buffer' && c.tokens > 0)
    const free = b.categories.find(c => c.kind === 'free')
    const reserve: Row[] = [
      ...(buffer !== undefined ? [{ name: buffer.name, tokens: buffer.tokens, color: RULE }] : []),
      ...(free !== undefined ? [{ name: free.name, tokens: free.tokens, color: TRACK, empty: true }] : []),
    ]
    const deferred: Row[] = b.categories
      .filter(c => c.kind === 'deferred' && c.tokens > 0)
      .map(c => ({ name: c.name, tokens: c.tokens, color: RULE, dim: true }))
    const max = Math.max(1, b.rawMaxTokens)
    const segments: Segment[] = [
      ...used.map(r => ({ fraction: r.tokens / max, color: r.color, label: `${r.name}: ${tok1(r.tokens)}` })),
      ...(free !== undefined ? [{ fraction: free.tokens / max, color: 'transparent', label: `${free.name}: ${tok1(free.tokens)}` }] : []),
      ...(buffer !== undefined ? [{ fraction: buffer.tokens / max, color: RULE, label: `${buffer.name}: ${tok1(buffer.tokens)}` }] : []),
    ]
    return { used, reserve, deferred, segments, max }
  }

  const dot = (color: string, empty?: boolean) =>
    Svg !== undefined ? (
      <Svg source={swatchSvg(color)} alt="" width={10} height={10} />
    ) : empty === true ? (
      <Text dimColor>□</Text>
    ) : (
      <Text color={color}>■</Text>
    )

  /** One line: swatch and name, then tokens and share in fixed right-aligned columns. */
  const contextRow = (r: Row, max: number) => (
    <Box key={r.name} columnGap={1} alignItems="center">
      <Box columnGap={1} flexGrow={1} flexShrink={1} alignItems="center">
        {dot(r.color, r.empty)}
        <Text dimColor={r.dim} wrap="truncate-end">
          {r.name}
        </Text>
      </Box>
      <Box width={7} justifyContent="flex-end">
        <Text {...num} dimColor>
          {tok1(r.tokens)}
        </Text>
      </Box>
      <Box width={6} justifyContent="flex-end">
        <Text {...num} dimColor={r.dim}>
          {r.dim === true ? '—' : pct1(r.tokens, max)}
        </Text>
      </Box>
    </Box>
  )

  /** "28% used · 281.4k / 1M" over a thin bar. */
  const contextHead = (b: SessionContextBreakdown, segments: readonly Segment[], marker?: number) => (
    <Box key="head" flexDirection="column" marginBottom={1}>
      <Box justifyContent="space-between">
        <Text bold color={b.percentage >= 65 ? level(b.percentage, 65, 85) : undefined}>{`${b.percentage}% used`}</Text>
        <Text {...num} dimColor>{`${tok1(b.totalTokens)} / ${tok1(b.rawMaxTokens)}`}</Text>
      </Box>
      {Svg !== undefined ? (
        <Svg source={stackedSvg(segments, 640, 6, marker)} alt={`Context ${b.percentage}% used`} isInteractive />
      ) : (
        stacked('bar', segments, 'Context by category', marker)
      )}
    </Box>
  )

  const noBreakdown = (key: string) => (
    <Text key={key} dimColor>
      {ctx?.tokens !== undefined ? `${tokens(ctx.tokens)} of ${tokens(ctx.window)} · breakdown loading` : 'The breakdown appears after the first response.'}
    </Text>
  )

  /** A collapsible list: a chevron row with its count, and its rows when open. */
  const section = (key: string, name: string, count: string, rows: () => RenderElement[]) => {
    const isOpen = open.includes(key)
    return (
      <Box key={key} flexDirection="column">
        <Box justifyContent="space-between" alignItems="center">
          <Button
            key={`exp-${key}`}
            plain
            onPress={() => update($, expanded, l => ((l ?? []).includes(key) ? (l ?? []).filter(k => k !== key) : [...(l ?? []), key]))}
          >
            {isOpen ? '⌄' : '›'} {name}
          </Button>
          <Text {...num} dimColor>
            {count}
          </Text>
        </Box>
        {isOpen && (
          <Box flexDirection="column" paddingLeft={2}>
            {rows()}
          </Box>
        )}
      </Box>
    )
  }

  const detailRow = (key: string, name: string, value: string, note?: string) => (
    <Box key={key} columnGap={1}>
      <Box flexGrow={1} flexShrink={1}>
        <Text wrap="truncate-end">
          {name}
          {note !== undefined && <Text dimColor>{` ${note}`}</Text>}
        </Text>
      </Box>
      <Box width={7} justifyContent="flex-end">
        <Text {...num} dimColor>
          {value}
        </Text>
      </Box>
    </Box>
  )

  const more = (key: string, n: number, what: string) =>
    n > 0 ? [<Text key={key} dimColor>{`+${n} more ${what}`}</Text>] : []

  const contextTab = (): RenderElement[] => {
    if (breakdown === undefined) return [noBreakdown('none')]
    const { used, reserve, deferred, segments, max } = contextRows(breakdown)
    const threshold = breakdown.autoCompactThreshold
    const marker = breakdown.isAutoCompactEnabled && threshold !== undefined ? threshold / max : undefined

    const servers = new Map<string, { tokens: number; tools: number; deferred: number }>()
    for (const t of breakdown.mcpTools) {
      const s = servers.get(t.serverName) ?? { tokens: 0, tools: 0, deferred: 0 }
      servers.set(t.serverName, { tokens: s.tokens + t.tokens, tools: s.tools + 1, deferred: s.deferred + (t.isLoaded ? 0 : 1) })
    }
    const byServer = [...servers.entries()].sort((a, b) => b[1].tokens - a[1].tokens)
    const memory = [...breakdown.memoryFiles].sort((a, b) => b.tokens - a.tokens)
    const skills = breakdown.skills
    const skillRows = skills !== undefined ? [...skills.skillFrontmatter].sort((a, b) => b.tokens - a.tokens) : []
    const agents = [...breakdown.agents].sort((a, b) => b.tokens - a.tokens)
    const LIMIT = 12

    return [
      <Box key="stats" flexWrap="wrap" marginBottom={1}>
        {stat('ac', 'Until auto-compact', breakdown.isAutoCompactEnabled && threshold !== undefined ? tok1(Math.max(0, threshold - breakdown.totalTokens)) : 'off')}
        {stat('api', 'Last response', breakdown.apiUsage !== null ? tok1(promptOf({ input: breakdown.apiUsage.input_tokens, cacheRead: breakdown.apiUsage.cache_read_input_tokens, cacheWrite: breakdown.apiUsage.cache_creation_input_tokens })) : '—')}
        {stat('model', 'Window of', modelName(breakdown.model))}
      </Box>,
      card(
        'context',
        'Context',
        [
          contextHead(breakdown, segments, marker),
          ...used.map(r => contextRow(r, max)),
          ...reserve.map(r => contextRow(r, max)),
          ...(deferred.length > 0 ? [<Box key="gap-deferred" marginTop={1} />, ...deferred.map(r => contextRow(r, max))] : []),
          <Box key="gap-sections" marginTop={1} />,
          ...(byServer.length > 0
            ? [
                section('mcp', 'MCP tools', String(breakdown.mcpTools.length), () => [
                  ...byServer
                    .slice(0, LIMIT)
                    .map(([name, s]) => detailRow(name, name, tok1(s.tokens), `${s.tools} tools${s.deferred > 0 ? ` · ${s.deferred} deferred` : ''}`)),
                  ...more('more-mcp', byServer.length - LIMIT, 'servers'),
                ]),
              ]
            : []),
          ...(memory.length > 0
            ? [
                section('memory', 'Memory files', String(memory.length), () =>
                  memory.slice(0, LIMIT).map(m => detailRow(m.path, tail(m.path, 3), tok1(m.tokens), m.type)),
                ),
              ]
            : []),
          ...(skills !== undefined && skills.totalSkills > 0
            ? [
                section('skills', 'Skills', `${skills.includedSkills}/${skills.totalSkills}`, () => [
                  ...skillRows.slice(0, LIMIT).map(k => detailRow(k.name, k.name, tok1(k.tokens), k.pluginName)),
                  ...more('more-skills', skillRows.length - LIMIT, 'skills'),
                ]),
              ]
            : []),
          ...(agents.length > 0
            ? [
                section('agents', 'Agent types', String(agents.length), () =>
                  agents.slice(0, LIMIT).map(a => detailRow(a.agentType, a.agentType, tok1(a.tokens), a.source)),
                ),
              ]
            : []),
          ...(breakdown.slashCommands !== undefined
            ? [detailRow('commands', 'Slash commands', tok1(breakdown.slashCommands.tokens), `${breakdown.slashCommands.includedCommands}/${breakdown.slashCommands.totalCommands}`)]
            : []),
        ],
        '100%',
      ),
    ]
  }

  // Cache

  const cacheHero = (key: string): RenderElement => {
    const fraction = cache.kind === 'warm' ? cache.remainingMs / opts.ttlMs : 0
    const color = cache.kind === 'warm' ? (cache.remainingMs <= warnMs ? STATUS.warning : STATUS.good) : STATUS.serious
    const big = cache.kind === 'warm' ? short(cache.remainingMs) : cache.kind === 'expired' ? 'Cold' : '—'
    const sub =
      cache.kind === 'warm'
        ? `left of ${opts.ttlLabel} · refreshed by each request`
        : cache.kind === 'expired'
          ? `idle ${short(cache.agoMs)} · next request re-caches ~${tokens(promptOf(cache.last) + cache.last.output)}`
          : 'waiting for the first request'
    return (
      <Box key={key} columnGap={2} alignItems="center">
        {gauge('ring', fraction, color, `Cache ${big}`)}
        <Box flexDirection="column">
          <Text {...title} color={color}>
            {big}
          </Text>
          <Text dimColor>{sub}</Text>
        </Box>
      </Box>
    )
  }

  const hitChart = (key: string, height: number) => (
    <Box key={key} flexDirection="column" marginTop={1}>
      {label(`Hit rate · last ${list.length} requests`)}
      {list.length > 0 ? chart('chart', hitColumns, `Cache hit rate per request, ${sessionHit}% overall`, height, 100, 80) : <Text dimColor>No requests yet.</Text>}
      {legend('legend', [
        [ACCENT, 'hit %'],
        [STATUS.critical, 'cache break'],
        [RULE, '80% guide'],
      ])}
    </Box>
  )

  const cacheTab = (): RenderElement[] => {
    const last = list.at(-1)
    return [
      cacheHero('hero'),
      <Box key="stats" flexWrap="wrap" marginTop={1}>
        {stat('session', 'Session hit', `${sessionHit}%`, level(100 - sessionHit, 20, 50))}
        {last !== undefined && stat('last', 'Last hit', `${hitOf(last)}%`)}
        {stat('read', 'Read', tokens(sum.cacheRead))}
        {stat('wrote', 'Written', tokens(sum.cacheWrite))}
        {stat('fresh', 'Uncached', tokens(sum.input))}
        {stat('breaks', 'Breaks', String(cut.length), cut.length > 0 ? STATUS.serious : undefined)}
      </Box>,
      hitChart('hits', 72),
      card(
        'breaks',
        'Cache breaks',
        cut.length === 0
          ? [<Text key="none" dimColor>None: every request reused the prefix before it.</Text>]
          : cut
              .slice(-6)
              .reverse()
              .map(b => (
                <Box key={String(b.at)} flexDirection="column" marginBottom={1}>
                  <Text>
                    <Text color={STATUS.critical}>● </Text>
                    <Text {...num} dimColor>
                      {clock(b.at)}{' '}
                    </Text>
                    {b.cause}
                  </Text>
                  <Text dimColor>{`   re-cached ${tokens(b.rewritten)} · read ${tokens(b.read)} of ${tokens(b.expected)} expected`}</Text>
                </Box>
              )),
        '100%',
      ),
      card(
        'recent',
        'Recent requests',
        [
          <Text key="head" dimColor mono>
            {`${'time'.padEnd(9)}${'hit'.padStart(5)}${'read'.padStart(8)}${'write'.padStart(8)}${'new'.padStart(7)}${'out'.padStart(7)}`}
          </Text>,
          ...list
            .slice(-8)
            .reverse()
            .map(r => (
              <Text key={String(r.at)} mono color={r.isBreak === true ? STATUS.critical : hitOf(r) < 80 ? STATUS.warning : undefined}>
                {`${clock(r.at).padEnd(9)}${`${hitOf(r)}%`.padStart(5)}${tokens(r.cacheRead).padStart(8)}${tokens(r.cacheWrite).padStart(8)}${tokens(r.input).padStart(7)}${tokens(r.output).padStart(7)}`}
              </Text>
            )),
        ],
        '100%',
      ),
      ...(sum.subagentRequests > 0
        ? [<Text key="sub" dimColor>{`Subagents made ${sum.subagentRequests} requests on caches of their own, not counted here.`}</Text>]
        : []),
    ]
  }

  // Turns

  const turnsTab = (): RenderElement[] => {
    const n = done.length
    const avg = n > 0 ? done.reduce((s, t) => s + t.durationMs, 0) / n : 0
    const toolsPer = n > 0 ? done.reduce((s, t) => s + t.tools, 0) / n : 0
    const calls = toolStats.reduce((s, t) => s + t.calls, 0)
    const errs = toolStats.reduce((s, t) => s + t.errors, 0)
    const costPer = n > 0 ? done.reduce((s, t) => s + t.costUsd, 0) / n : 0
    const top = [...toolStats].sort((a, b) => b.calls - a.calls).slice(0, 8)
    const most = Math.max(1, ...top.map(t => t.calls))
    const durations: Column[] = done.map(t => ({
      value: t.durationMs / 1000,
      color: t.reason === 'answer' ? ACCENT : t.reason === 'aborted' ? RULE : STATUS.serious,
      label: `${clock(t.at)} · ${duration(t.durationMs)} · ${t.requests} requests · ${t.tools} tools · ${usd(t.costUsd)}`,
    }))

    return [
      ...(running !== null
        ? [
            <Box key="live" columnGap={1} marginBottom={1}>
              <Text color={STATUS.good}>● Running</Text>
              <Text dimColor>{`${short(now - running.startedAt)} · ${running.requests} requests · ${running.tools} tools${running.errors > 0 ? ` · ${running.errors} failed` : ''}`}</Text>
            </Box>,
          ]
        : []),
      <Box key="stats" flexWrap="wrap">
        {stat('turns', 'Turns', String(n))}
        {stat('avg', 'Avg duration', n > 0 ? duration(avg) : '—')}
        {stat('tools', 'Tools / turn', n > 0 ? toolsPer.toFixed(1) : '—')}
        {stat('errors', 'Tool errors', calls > 0 ? `${percent(errs, calls)}%` : '—', errs > 0 ? STATUS.serious : undefined)}
        {stat('cost', 'Cost / turn', n > 0 ? usd(costPer) : '—')}
      </Box>,
      <Box key="durations" flexDirection="column" marginTop={1}>
        {label(`Duration · last ${n} turns`)}
        {n > 0 ? chart('chart', durations, `Turn durations, average ${duration(avg)}`, 72, undefined, avg / 1000) : <Text dimColor>No finished turns yet.</Text>}
        {legend('legend', [
          [ACCENT, 'answered'],
          [STATUS.serious, 'error or refusal'],
          [RULE, 'interrupted · dashed: average'],
        ])}
      </Box>,
      card(
        'tools',
        'Tools',
        top.length === 0
          ? [<Text key="none" dimColor>No tool calls yet.</Text>]
          : top.map(t => (
              <Box key={t.tool} columnGap={1} alignItems="center">
                <Box width={18}>
                  <Text wrap="truncate-end">{t.tool}</Text>
                </Box>
                {Svg !== undefined ? (
                  <Svg source={meterSvg(t.calls / most, ACCENT)} alt={`${t.calls} calls`} width={140} height={8} />
                ) : (
                  <Text color={ACCENT}>{textBar(t.calls / most, 12)[0].padEnd(12)}</Text>
                )}
                <Text {...num}>{String(t.calls).padStart(4)}</Text>
                <Text {...num} dimColor>
                  {`${short(t.totalMs / t.calls)} avg`}
                </Text>
                {t.errors > 0 && <Text color={STATUS.critical}>{`${t.errors} failed`}</Text>}
              </Box>
            )),
        '100%',
      ),
    ]
  }

  // Overview

  const overviewTab = (): RenderElement[] => {
    const costs: Column[] = done.map(t => ({ value: t.costUsd, color: ACCENT, label: `${clock(t.at)} · ${usd(t.costUsd)}` }))
    const hasFill = ctx?.tokens !== undefined
    const ctxColor = hasFill ? level(ctxPct, 65, 85) : RULE
    const threshold = breakdown?.isAutoCompactEnabled === true ? breakdown.autoCompactThreshold : undefined
    const contextCard = card('ctx', 'Context', [
      <Box key="hero" columnGap={2} alignItems="center">
        {gauge('ring', hasFill ? ctxPct / 100 : 0, ctxColor, `Context ${ctxPct}% used`)}
        <Box flexDirection="column">
          <Text {...title} color={hasFill ? ctxColor : undefined}>
            {hasFill ? `${ctxPct}%` : '—'}
          </Text>
          <Text dimColor>{hasFill ? `${tok1(ctx.tokens ?? 0)} of ${tok1(ctx.window)} used` : 'waiting for the first response'}</Text>
        </Box>
      </Box>,
      <Text key="line" dimColor>
        {breakdown !== undefined
          ? threshold !== undefined
            ? `${tok1(Math.max(0, threshold - breakdown.totalTokens))} until auto-compact`
            : 'Auto-compact off'
          : ' '}
      </Text>,
    ])

    const cacheCard = card('cache', 'Prompt cache', [
      cacheHero('hero'),
      <Text key="hit" dimColor>
        {list.length > 0 ? `Hit ${hitOf(list.at(-1) ?? list[0]!)}% last · ${sessionHit}% session${cut.length > 0 ? ` · ${cut.length} breaks` : ''}` : ' '}
      </Text>,
    ])

    const costCard = card('cost', 'Cost', [
      <Text key="big" {...title}>
        {usage?.cost !== undefined ? usd(usage.cost.usd) : '—'}
      </Text>,
      <Text key="sub" dimColor>
        {done.length > 0 ? `${usd(done.reduce((s, t) => s + t.costUsd, 0) / done.length)} per turn · ${done.length} turns` : 'no finished turns yet'}
      </Text>,
      ...(done.length > 1 ? [chart('chart', costs, 'Cost per turn', 36)] : []),
    ])

    const limits = usage?.rateLimits ?? []
    const limitsCard = card(
      'limits',
      'Rate limits',
      limits.length === 0
        ? [<Text key="none" dimColor>No reading yet.</Text>]
        : limits.map(l => {
            const color = level(l.percentUsed, 70, 90)
            const resets = l.resetsAt !== undefined ? ` · resets ${short(Date.parse(l.resetsAt) - now)}` : ''
            return (
              <Box key={l.kind} flexDirection="column" marginBottom={1}>
                <Box justifyContent="space-between">
                  <Text>{limitName(l.kind)}</Text>
                  <Text {...num} dimColor>{`${l.percentUsed}%${resets}`}</Text>
                </Box>
                {Svg !== undefined ? (
                  <Svg source={meterSvg(l.percentUsed / 100, color, 320, 8)} alt={`${limitName(l.kind)} ${l.percentUsed}%`} />
                ) : (
                  <Text>
                    <Text color={color}>{textBar(l.percentUsed / 100, 24)[0]}</Text>
                    <Text dimColor>{textBar(l.percentUsed / 100, 24)[1]}</Text>
                  </Text>
                )}
              </Box>
            )
          }),
    )

    const branch =
      repo !== null
        ? `⎇ ${repo.branch}${repo.dirty > 0 ? ` · ${repo.dirty} changed` : ' · clean'}${repo.ahead > 0 ? ` · ↑${repo.ahead}` : ''}${repo.behind > 0 ? ` · ↓${repo.behind}` : ''}`
        : undefined

    const sessionCard = card(
      'session',
      'Session',
      [
        ...(branch !== undefined ? [line('git', 'Branch', branch, repo !== null && repo.dirty > 0 ? STATUS.warning : undefined)] : []),
        ...(cwd !== undefined ? [line('cwd', 'Directory', tail(cwd, 3))] : []),
        ...(usage !== undefined ? [line('up', 'Running', `${duration(now - usage.startedAt)} · since ${clock(usage.startedAt)}`)] : []),
        ...(prompts !== undefined ? [line('prompts', 'Prompts', String(prompts))] : []),
        ...(model !== undefined ? [line('model', 'Model', model)] : []),
        ...(version !== undefined ? [line('version', 'Claude Code', version.version)] : []),
        ...(id !== undefined ? [line('id', 'Session id', id)] : []),
        <Box key="actions" columnGap={1} marginTop={1}>
          {id !== undefined && (
            <Button
              key="copy"
              label="Copy session id"
              onPress={async () => {
                const copied = await $.ui.copy({ text: id, surface: e.surface })
                $.ui.toast(copied.isCopied ? 'Session id copied' : 'Could not reach the clipboard')
              }}
            />
          )}
          <Button
            key="compact"
            label="Compact now"
            onPress={async () => {
              try {
                const done = await $.session.compact()
                $.ui.toast(done.skip === undefined ? 'Conversation compacted' : `Compaction skipped: ${done.skip}`)
              } catch {
                $.ui.toast('Compaction runs between turns; try again when Claude is idle')
              }
            }}
          />
        </Box>,
      ],
      '100%',
    )

    return [
      <Box key="cards" flexWrap="wrap" columnGap={1}>
        {contextCard}
        {cacheCard}
        {costCard}
        {limitsCard}
      </Box>,
      hitChart('hits', 48),
      <Box key="gap" marginTop={1} />,
      sessionCard,
    ]
  }

  const body =
    current === 'context' ? contextTab() : current === 'cache' ? cacheTab() : current === 'turns' ? turnsTab() : overviewTab()

  return (
    <Box flexDirection="column">
      {header}
      {body}
    </Box>
  )
}

