/** One main-loop API request, as its usage reported it. */
export type CacheRequest = {
  at: number
  model: string
  input: number
  cacheRead: number
  cacheWrite: number
  output: number
  /** Set when this request re-cached a prefix the previous one had cached. */
  isBreak?: boolean
}

/** Token counts summed over every main-loop request this session. */
export type CacheTotals = {
  requests: number
  input: number
  cacheRead: number
  cacheWrite: number
  output: number
  subagentRequests: number
}

/** A request whose cache read fell well short of the prefix cached before it. */
export type CacheBreak = {
  at: number
  /** Tokens written to the cache by the breaking request. */
  rewritten: number
  /** Tokens the cache served, against what the previous request had cached. */
  read: number
  expected: number
  cause: string
}

/** One finished main-loop turn. */
export type TurnStat = {
  at: number
  durationMs: number
  requests: number
  tools: number
  errors: number
  costUsd: number
  outputTokens: number
  reason: string
}

/** The turn running now, filled as its requests and tool calls land. */
export type TurnInFlight = {
  turnId: string
  startedAt: number
  costAtStart: number
  requests: number
  tools: number
  errors: number
}

export type ToolStat = { tool: string; calls: number; errors: number; totalMs: number }

/** What happened since the last main-loop request, read to explain a break. */
export type Signals = { compactedAt: number; promptKey: string; promptChangedAt: number }

/** Which alerts have fired, so each fires once. */
export type Alerts = { expiryFor: number; contextLevel: number }

export type GitInfo = { branch: string; dirty: number; ahead: number; behind: number }

export type Tab = 'overview' | 'context' | 'cache' | 'turns'

declare module 'claude-code' {
  interface PluginState {
    'session-info': {
      requests: CacheRequest[]
      totals: CacheTotals
      tick: number
      breaks: CacheBreak[]
      turns: TurnStat[]
      turn: TurnInFlight | null
      tools: ToolStat[]
      signals: Signals
      alerts: Alerts
      git: GitInfo | null
      tab: Tab
      /** Which collapsible sections of the context card are open. */
      expanded: string[]
    }
  }
}
